using FMODUnity;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

public class StarAbility : ScriptableObject
{
	private const string orbRequirementID = "OrbRequirement";

	[Header("Description ID")]
	[SerializeField]
	private string starAbilityID;

	[Header("Effects and Tags")]
	[SerializeField]
	private Effect[] effects;

	[SerializeField]
	private Tag[] tags;

	[Header("StarAbilityReference")]
	[SerializeField]
	private StarAbilityReference starAbilityReference;

	[Header("Sprite")]
	[SerializeField]
	private Sprite starAbilitySprite;

	[Header("SFX")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	private bool enableSFX;

	[SerializeField]
	[ShowIf("enableSFX")]
	private EventReference actionSFX;

	public string StarAbilityID => starAbilityID;

	public Effect[] Effects => effects;

	public Tag[] Tags => tags;

	public Sprite StarAbilitySprite => starAbilitySprite;

	public string GetLocalizedName(bool addActiveOrb)
	{
		string text = GetLocalizedNameWithoutModifiers();
		if (addActiveOrb && starAbilityReference.Value == this)
		{
			text += ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("ActiveOrb");
		}
		return text;
	}

	public string GetLocalizedNameWithoutModifiers()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(starAbilityID + "_N");
	}

	public virtual string GetLocalizedDescription()
	{
		return "";
	}

	protected string GetCastOrbLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CastOrbFormmat");
	}

	public virtual string GetLocalizedRequirement()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("OrbRequirement"), GetLocalizedNameWithoutModifiers(), starAbilityID);
	}

	public virtual void Initialize()
	{
	}

	public virtual void OnEnteringStar()
	{
	}

	public virtual void OnExitingStar()
	{
	}

	public virtual void OnEndTurnStarAbility()
	{
	}

	public virtual void OnStartTurnStarAbility()
	{
	}

	public virtual void OnActivateStarAbility()
	{
	}

	public void PlaySFX()
	{
		if (enableSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(actionSFX);
		}
	}
}
